-- match_boards/pairs: 23 boards, 92 pairs for subject accounts.

MERGE INTO match_boards AS t
USING (
    SELECT v.question_code, c.id AS chapter_id, v.prompt, v.difficulty, v.points, v.hint, v.explanation
    FROM (VALUES
        ('acc11-01-mf-0001', 1, 'Match each Fundamental Accounting Concept with its Definition:', 2, 40, 'These core GAAP conventions guide the valuation and reporting of accounts.', 'Dual Aspect dictates total Debits must equal Credits, Going Concern presumes indefinite entity life, Money Measurement only records events quantifiable in money, and Conservatism anticipates potential losses.'),
        ('acc11-01-mf-0002', 1, 'Match each Form of Business Organization with its Key Attribute:', 1, 40, 'Look at ownership structure, legal status, and mutual association requirements.', 'Sole Proprietorship is run by a single owner, Partnership requires a minimum of 2 partners, a Company is an incorporated separate legal entity, and Cooperatives are voluntary associations for mutual help.'),
        ('acc11-01-mf-0003', 1, 'Match each System / Basis of Accounting with its Underlying Principle:', 2, 40, 'Compare strict cash timing versus period matching and single versus dual entry.', 'Cash basis waits for cash movements; accrual basis reflects economic events when incurred; single entry is incomplete; double entry systematically records both sides of every transaction.'),
        ('acc11-01-mf-0004', 1, 'Match each Term related to Solvency with its Definition:', 1, 40, 'Examine financial capability to meet commercial liabilities and debt collection risks.', 'A solvent person can honor debts; an insolvent person cannot; bad debts are confirmed uncollectible; doubtful debts represent estimated recovery risk.'),
        ('acc11-01-mf-0005', 1, 'Match each Branch of Accounting with its Primary Target Objective:', 2, 40, 'Consider who consumes the information and for what purpose.', 'Financial accounting serves banks/investors; cost accounting guides factory/pricing managers; management accounting aids strategic planning; social accounting measures CSR.'),
        ('acc11-01-mf-0006', 1, 'Match each Accounting Standard (AS / Ind AS) with its Regulatory Subject:', 3, 40, 'Standardized disclosure and valuation guidance issued by ICAI.', 'AS 1 mandates policy disclosure; AS 2 guides inventory cost vs NRV; AS 9 governs revenue timing; AS 10 governs fixed asset capitalization and depreciation.'),
        ('acc11-02-mf-0002', 2, 'Match each Golden Rule / Concept with its Core Principle:', 1, 40, 'Recall the classic double-entry rules for personal, real, and nominal accounts.', 'Personal Account: Debit the receiver, Credit the giver. Real Account: Debit what comes in, Credit what goes out. Nominal Account: Debit all expenses, Credit all incomes. Capital represents a liability of the business entity to its proprietor.'),
        ('acc11-02-mf-0003', 2, 'Match each Type of Personal Account with its Representative Example:', 1, 40, 'Distinguish between human beings, legal entities/institutions, and accounts representing a group.', 'Sunita is a natural human person; Bank of Maharashtra is an artificial person created by law; Outstanding Salary represents employees due payments; Drawings is personal account of the owner.'),
        ('acc11-02-mf-0004', 2, 'Match each Real Account Asset with its Precise Sub-Category:', 1, 40, 'Consider physical tangibility and how quickly the asset converts to cash.', 'Motor Car has physical existence and long life; Copyright has no physical form but legal value; Stock is held for trade; Cash is the most liquid asset.'),
        ('acc11-02-mf-0005', 2, 'Match each Transaction Type with its Defining Feature:', 1, 40, 'Focus on the timing of cash settlement and whether currency is involved.', 'Cash transactions settle immediately; credit transactions create debtor/creditor relationships; non-cash transactions include depreciation or fire loss; barter trades goods directly.'),
        ('acc11-02-mf-0006', 2, 'Match each Accounting Equation Element with its Calculation / Formula:', 1, 40, 'Use the fundamental dual-aspect equation: Assets = Liabilities + Capital.', 'The balance sheet equation balances resources (assets) against obligations (liabilities) and owner investments (capital).'),
        ('acc11-02-mf-0007', 2, 'Match each Account Balance Behavior with its Standard Ledger Classification:', 1, 40, 'Recall the modern classification of accounts and ledger rules for increases/decreases.', 'Assets and expenses naturally hold debit balances; liabilities, revenues, and capital hold credit balances; increases follow the normal balance side.'),
        ('acc11-02-mf-0008', 2, 'Match each Golden Rule of Accounting with its Applicable Account Class:', 1, 40, 'Link each traditional 3-part Golden Rule to Personal, Real, or Nominal accounts.', 'Personal accounts track receivers/givers; Real accounts track asset inflows/outflows; Nominal accounts track expenses and earnings.'),
        ('acc11-02-mf-0009', 2, 'Match each Commercial Entity Type with its Distinct Characteristic:', 2, 40, 'Classification based on legal identity and institutional formation.', 'Sole traders are natural persons; companies and banks are artificial corporate persons; prepaid/outstanding accounts are representative; clubs are non-profit service bodies.'),
        ('acc11-03-mf-0001', 3, 'Match each Accounting Document / Voucher with its Commercial Function:', 2, 40, 'Think about buyer-seller communications when buying, selling, or returning merchandise.', 'Cash memo records cash transactions; tax invoice bills credit sales; debit note debits the supplier account on purchase returns; credit note credits customer account on sales returns.'),
        ('acc11-03-mf-0002', 3, 'Match each Discount Type with its Bookkeeping Recording Rule:', 2, 40, 'Determine whether the concession appears explicitly as a ledger entry in financial accounts.', 'Trade discounts reduce catalogue prices without journal entry; cash and settlement discounts incentivize early liquidation and are explicitly ledger-posted.'),
        ('acc11-05-mf-0001', 5, 'Match each Subsidiary Book with the Nature of Entries it Contains:', 2, 40, 'Remember that special journals handle high-volume routine transactions while Journal Proper catches the rest.', 'Purchases and Sales books record trade goods on credit; Cash book logs all liquid cash flows; Journal Proper handles adjustments and non-cash asset trades.'),
        ('acc11-06-mf-0001', 6, 'Match each Banking Term / Instrument with its Description:', 1, 40, 'Identify typical commercial banking instruments and records.', 'A cheque is a negotiable instrument, passbook is a bank-issued copy of customer''s account, overdraft is an approved credit line facility, and ATM stands for Automated Teller Machine.'),
        ('acc11-07-mf-0001', 7, 'Match each Depreciation Method with its Distinguishing Trait:', 2, 40, 'Examine how depreciation expense is allocated across the asset''s useful life.', 'Straight Line charges equal amounts each year, Written Down Value charges decreasing amounts on book value, Sinking Fund accumulates investments to replace the asset, and Annuity Method includes interest on capital outlay.'),
        ('acc11-08-mf-0001', 8, 'Match each Type of Accounting Error with its Characteristic:', 2, 40, 'Consider how trial balance errors arise in recording, posting, and classification.', 'Error of Omission means a transaction was left out completely, Error of Commission involves clerical mistakes like wrong amounts or cast errors, Error of Principle misapplies capital/revenue distinctions, and Compensating Errors offset each other.'),
        ('acc11-08-mf-0002', 8, 'Match each Trial Balance Error with its Trial Balance Detection Outcome:', 3, 40, 'Check whether the error affects only one side or both debit and credit equally.', 'Trial balance only catches arithmetical one-sided errors; complete omissions, errors of principle, and compensating errors still leave debits equal to credits.'),
        ('acc11-09-mf-0001', 9, 'Match each Financial Statement with its Core Purpose:', 1, 40, 'Consider the primary financial insight each statement delivers to stakeholders.', 'Balance Sheet reflects financial position, Profit & Loss shows net profit or loss, Cash Flow tracks cash inflows and outflows, and Trial Balance checks arithmetical accuracy of ledger postings.'),
        ('acc11-09-mf-0002', 9, 'Match each Asset with its Accounting Category:', 1, 40, 'Classify by physical existence, liquidity, and operational lifespan.', 'Goodwill has no physical form (Intangible), Stock turns to cash in under a year (Current), Building lasts multiple periods (Fixed), and Preliminary Expenses represent unwritten-off fictitious items.')
    ) AS v (question_code, chapter_no, prompt, difficulty, points, hint, explanation)
    JOIN chapters c ON c.chapter_no = v.chapter_no
    JOIN subjects sub ON sub.id = c.subject_id AND sub.code = 'accounts'
) AS s
ON t.question_code = s.question_code
WHEN MATCHED AND (t.chapter_id, t.prompt, t.difficulty, t.points, t.hint, t.explanation) IS DISTINCT FROM (s.chapter_id, s.prompt, s.difficulty, s.points, s.hint, s.explanation) THEN
    UPDATE SET chapter_id = s.chapter_id, prompt = s.prompt, difficulty = s.difficulty, points = s.points, hint = s.hint, explanation = s.explanation
WHEN NOT MATCHED THEN
    INSERT (question_code, chapter_id, prompt, difficulty, points, hint, explanation) VALUES (s.question_code, s.chapter_id, s.prompt, s.difficulty, s.points, s.hint, s.explanation)
WHEN NOT MATCHED BY SOURCE AND t.chapter_id IN (SELECT c.id FROM chapters c JOIN subjects sub ON sub.id = c.subject_id WHERE sub.code = 'accounts') THEN
    DELETE;

